from scipy.io import mmread
import scipy as sp
import torch
import numpy as np

def load_matrix():
    # path to your MatrixMarket file
    path = "LU_matrix_l1_r0.mtx"
    sp_matrix = mmread(path).tocoo()  # ensure COO format


    # Extract COO components
    row  = torch.from_numpy(sp_matrix.row.astype(int))
    col  = torch.from_numpy(sp_matrix.col.astype(int))
    vals = torch.from_numpy(sp_matrix.data)         # float or whatever dtype

    # Stack row & col into a 2×nnz indices tensor
    indices = torch.stack([row, col], dim=0)

    # Create the sparse tensor
    shape = torch.Size(sp_matrix.shape)
    sparse_tensor = torch.sparse_coo_tensor(indices, vals, shape)

    # (Optional) coalesce to sum duplicates, if any:
    A = sparse_tensor.coalesce() # .to_dense()

    return A, sp_matrix

