def main():
    u, H_mat = b_and_x()

    e = torch.zeros_like(u)
    e[0] = 6.08032

    print(f'{H_mat.shape = }, {e.shape = }')
    row_norms = H_mat.norm(dim=0)
    D_inv = torch.diag(1 / row_norms)
    H_mat_ = H_mat @ D_inv
    print(H_mat_)
    u_pred = torch.linalg.lstsq(H_mat_, e, driver="gels").solution
    u_pred = D_inv @ u_pred
    print(f'{u_pred = }')

    residual = -e + H_mat @ u_pred # u[:-1]
    print(f'{residual.norm() = }')

if __name__ == "__main__":
    main()

